{
  "schema_version": "focused_research.task_sheet.v2",
  "task_type": "design/optimization",
  "user_objective": "Design a planar HfO2/SiO2/Cr multilayer absorber on an aluminum substrate for solar-thermal applications, maximizing wavelength-integral mean absorption (minimizing reflectance) in the visible band and maximizing wavelength-integral mean reflectance in the NIR band at normal incidence under the stated constraints.",
  "subgoals": [
    {
      "id": "G1",
      "objective": "Maximize visible-band absorption (minimize reflectance)",
      "original_span": "在 400-700 nm 可见波段吸收率尽可能高（反射率尽可能低）",
      "operational_definition": "Wavelength integral of the specified optical quantity over the band, divided by band width, for equal-s/p unpolarized light at 0 degrees. Minimizing mean_reflectance is the executable proxy for maximizing absorption in this finite-film-on-absorber context.",
      "executable_metric": {
        "objective_id": "G1",
        "metric": "mean_reflectance",
        "sense": "minimize",
        "mean_reduction": "wavelength_integral_mean",
        "region": {
          "wavelength_nm": [
            400,
            700
          ],
          "angle_deg": 0,
          "polarization": "unpolarized"
        }
      }
    },
    {
      "id": "G2",
      "objective": "Maximize NIR-band reflectance to suppress heat input",
      "original_span": "在 700-2000 nm 近红外波段反射率尽可能高以抑制热输入",
      "operational_definition": "Wavelength integral of the specified optical quantity over the band, divided by band width, for equal-s/p unpolarized light at 0 degrees.",
      "executable_metric": {
        "objective_id": "G2",
        "metric": "mean_reflectance",
        "sense": "maximize",
        "mean_reduction": "wavelength_integral_mean",
        "region": {
          "wavelength_nm": [
            700,
            2000
          ],
          "angle_deg": 0,
          "polarization": "unpolarized"
        }
      }
    }
  ],
  "application_intents": [
    {
      "id": "A1",
      "intent": "Spectral selective surface for visible light heating paint",
      "original_span": "为可见光吸热涂料的光谱选择性表面设计吸收膜",
      "subgoal_ids": [
        "G1",
        "G2"
      ],
      "operational_definition": null
    },
    {
      "id": "A2",
      "intent": "Report power transmission into the stated semi-infinite exit substrate (aluminum) as part of the system absorptance calculation (1-R)",
      "original_span": "铝基底条件下",
      "subgoal_ids": [
        "G1"
      ],
      "operational_definition": "Treat the aluminum substrate as a semi-infinite absorbing exit medium; transmission into it contributes to total system absorption but is not a separate optimization objective."
    }
  ],
  "goal_relationships": {
    "mode": "all",
    "priority_order": null,
    "tradeoff": null,
    "coupling": "G1 and G2 are spectrally adjacent goals for the same coating stack; achieving high visible absorption often conflicts with maintaining high NIR reflectance due to material dispersion and interference coupling."
  },
  "explicit_constraints": [
    {
      "id": "C1",
      "constraint": "Visible band: 400–700 nm",
      "original_span": "400-700 nm"
    },
    {
      "id": "C2",
      "constraint": "NIR band: 700–2000 nm",
      "original_span": "700-2000 nm"
    },
    {
      "id": "C3",
      "constraint": "Incident medium: air",
      "original_span": "空气入射"
    },
    {
      "id": "C4",
      "constraint": "Substrate: aluminum",
      "original_span": "铝基底"
    },
    {
      "id": "C5",
      "constraint": "Coating materials: HfO2, SiO2, and Cr only",
      "original_span": "仅使用 HfO2 和 SiO2 与金属 Cr"
    },
    {
      "id": "C6",
      "constraint": "Planar multilayer film",
      "original_span": "平面多层膜"
    },
    {
      "id": "C7",
      "constraint": "No more than 20 layers",
      "original_span": "膜系总层数不超过 20 层"
    },
    {
      "id": "C8",
      "constraint": "Suppress heat input in NIR",
      "original_span": "以抑制热输入"
    }
  ],
  "known_data": [
    {
      "statement": "Application is a spectral selective surface for visible light heating paint",
      "original_span": "可见光吸热涂料的光谱选择性表面"
    }
  ],
  "unknowns_assumptions": [
    {
      "kind": "assumption",
      "statement": "Execution assumes 0 degree incidence, equal-s/p unpolarized light, and wavelength-integral band means, as these were not explicitly specified in the original question.",
      "assumed_value": "0 deg, unpolarized, wavelength_integral_mean",
      "needs_user_input": false
    },
    {
      "kind": "assumption",
      "statement": "The aluminum substrate is treated as a semi-infinite absorbing exit medium for the planar-surface calculation; T_into_substrate is not zero but contributes to system absorptance.",
      "assumed_value": "semi-infinite absorbing medium",
      "needs_user_input": false
    },
    {
      "kind": "unknown",
      "statement": "Optical constants/dispersion for HfO2, SiO2, Cr, and Al across 400-2000 nm, fabrication tolerances, and individual thickness bounds remain to be resolved.",
      "assumed_value": null,
      "needs_user_input": false
    },
    {
      "kind": "unknown",
      "statement": "Numerical acceptance thresholds and objective weights are unspecified; 'as high/low as possible' is not a fixed numeric threshold.",
      "assumed_value": null,
      "needs_user_input": false
    }
  ],
  "research_questions": [
    {
      "id": "R1",
      "question": "Which complete selective solar absorber designs demonstrate high visible absorption and high NIR reflectance using dielectric-metal stacks?",
      "subgoal_ids": [
        "G1",
        "G2"
      ]
    },
    {
      "id": "R2",
      "question": "How do HfO2/SiO2/Cr layer structures on aluminum affect spectral selectivity and thermal emittance?",
      "subgoal_ids": [
        "G1",
        "G2"
      ]
    },
    {
      "id": "R3",
      "question": "What optimization methods effectively balance visible absorption and NIR reflectance in thin-film stacks with metallic layers?",
      "subgoal_ids": [
        "G1",
        "G2"
      ]
    }
  ],
  "candidate_mechanisms": [
    {
      "id": "M1",
      "mechanism": "Interference in dielectric layers (HfO2/SiO2) can enhance absorption in the visible by trapping light in the Cr layer while maintaining high reflection in the NIR via a Bragg-like stack or impedance matching.",
      "subgoal_ids": [
        "G1",
        "G2"
      ],
      "status": "candidate"
    },
    {
      "id": "M2",
      "mechanism": "Metal-dielectric composite effects or cermets involving Cr may provide intrinsic broadband absorption tuned by layer thickness.",
      "subgoal_ids": [
        "G1"
      ],
      "status": "candidate"
    }
  ],
  "search_queries": [
    {
      "id": "Q1",
      "endpoint": "paper_search",
      "query": "selective solar absorber multilayer coating design visible absorption near infrared reflection",
      "subgoal_ids": [
        "G1",
        "G2"
      ],
      "mechanism_ids": [
        "M1"
      ],
      "research_question_ids": [
        "R1"
      ],
      "purpose": "analogous_case",
      "rationale": "Find analogous complete coating designs for spectral selective surfaces before narrower component studies."
    },
    {
      "id": "Q2",
      "endpoint": "snippet_search",
      "query": "Which multilayer coatings combine high visible absorptance and high near infrared reflectance for solar thermal applications?",
      "subgoal_ids": [
        "G1",
        "G2"
      ],
      "mechanism_ids": [
        "M1"
      ],
      "research_question_ids": [
        "R1"
      ],
      "purpose": "analogous_case",
      "rationale": "Find design passages describing the joint spectral function of absorbing visible and reflecting NIR."
    },
    {
      "id": "Q3",
      "endpoint": "paper_search",
      "query": "HfO2 SiO2 Cr multilayer solar absorber aluminum substrate optical properties",
      "subgoal_ids": [
        "G1",
        "G2"
      ],
      "mechanism_ids": [
        "M1",
        "M2"
      ],
      "research_question_ids": [
        "R2"
      ],
      "purpose": "material_structure",
      "rationale": "Seek material-specific optical performance of the requested HfO2/SiO2/Cr stack on aluminum."
    },
    {
      "id": "Q4",
      "endpoint": "snippet_search",
      "query": "How are dielectric metal multilayer spectral filters optimized for high visible absorption and low thermal emittance?",
      "subgoal_ids": [
        "G1",
        "G2"
      ],
      "mechanism_ids": [
        "M1"
      ],
      "research_question_ids": [
        "R3"
      ],
      "purpose": "method_transfer",
      "rationale": "Seek transferable layer-thickness synthesis methods for balancing absorption and reflection bands."
    },
    {
      "id": "Q5",
      "endpoint": "snippet_search",
      "query": "What is the role of chromium layers in enhancing visible absorption in dielectric multilayer solar selective coatings?",
      "subgoal_ids": [
        "G1"
      ],
      "mechanism_ids": [
        "M2"
      ],
      "research_question_ids": [
        "R2"
      ],
      "purpose": "mechanism",
      "rationale": "Investigate the specific mechanism of Cr as an absorber layer within the dielectric stack."
    }
  ],
  "unsupported_requirements": [],
  "readiness": "ready"
}

